package com.cryptox.controller; import com.cryptox.dto.*; import com.cryptox.service.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class WalletController{final WalletLedgerService s; final QrCodeService qr; @Value("${app.internal-key}") String key; String user(HttpServletRequest r){Object u=r.getAttribute("username"); if(u==null)throw new SecurityException(); return u.toString();}
@GetMapping("/api/wallet/me") ResponseEntity<?> me(HttpServletRequest r){try{return ResponseEntity.ok(s.response(s.byUser(user(r))));}catch(SecurityException e){return ResponseEntity.status(401).build();}} @GetMapping("/api/wallet/{id}") Object lookup(@PathVariable String id){s.byId(id);return Map.of("walletId",id,"exists","true");}
@GetMapping("/api/wallet/me/qrcode") ResponseEntity<?> q(HttpServletRequest r){try{var w=s.byUser(user(r));return ResponseEntity.ok(Map.of("walletId",w.getWalletId(),"qrCodeBase64Png",qr.generateQrCodeBase64(w.getWalletId(),300)));}catch(SecurityException e){return ResponseEntity.status(401).build();}}
@PostMapping("/api/transactions/send") ResponseEntity<?> send(HttpServletRequest r,@Valid @RequestBody SendCryptoRequest x){try{return ResponseEntity.ok(s.send(user(r),x));}catch(SecurityException e){return ResponseEntity.status(401).build();}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} @GetMapping("/api/transactions/history") ResponseEntity<?> hist(HttpServletRequest r){try{return ResponseEntity.ok(s.history(user(r)));}catch(SecurityException e){return ResponseEntity.status(401).build();}}
@PostMapping("/internal/wallets") ResponseEntity<?> create(@RequestHeader("X-Internal-Key") String k,@RequestBody InternalWalletCreateRequest x){if(!key.equals(k))return ResponseEntity.status(403).build();var w=s.create(x.username());return ResponseEntity.ok(Map.of("walletId",w.getWalletId()));}
@PostMapping("/internal/trades") ResponseEntity<?> trade(@RequestHeader("X-Internal-Key") String k,@RequestBody InternalTradeRequest x){if(!key.equals(k))return ResponseEntity.status(403).build();try{return ResponseEntity.ok(s.trade(x));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}}